import pandas as pd

path = "初级审计师20周备考计划.xlsx"
xl = pd.ExcelFile(path)

# 分析周计划打卡表：按阶段统计周数
df = xl.parse("周计划打卡", header=None)
df = df.iloc[2:]  # 去掉标题行
stage_map = {"①启动":"启动", "②基础":"基础精讲", "③强化":"强化刷题", "④模考":"真题模考", "⑤冲刺":"冲刺考试"}
stage_rows = {}
for _, r in df.iterrows():
    stage = str(r[1])
    if stage in stage_map:
        stage_rows.setdefault(stage, []).append(r)

print("=== 各阶段周数与主题 ===")
for stage, rows in stage_rows.items():
    print(f"\n【{stage_map[stage]}】共{len(rows)}周")
    for r in rows:
        print(f"  第{str(r[0]).replace('第','').replace('周','')}周 → {r[2]}")

